#!/usr/bin/env python3
"""Generates all inner pages in the same dark style as the homepage (css/home.css). Run: python3 build.py"""
import os
N = "HVAC Demo"
NAV = [("about", "About"), ("solutions", "Solutions"), ("industries", "Industries"), ("projects", "Projects"), ("technology", "Technology"), ("maintenance", "Maintenance"), ("insights", "Insights"), ("contact", "Contact")]
IMG = lambda n, alt, r="", cls="": f'<img class="{cls}" src="{r}assets/images/{n}.svg" alt="{alt}" loading="lazy">'
def head(title, desc, r, noindex):
    return (f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{title} | {N}</title>'
      f'<meta name="description" content="{desc}">{"<meta name=robots content=noindex>" if noindex else ""}<meta property="og:title" content="{title} | {N}"><meta name="theme-color" content="#06101C">'
      f'<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
      f'<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Sora:wght@600;700&display=swap"><link rel="stylesheet" href="{r}css/home.css"></head>')
def nav(r, cur):
    li = "".join(f'<li><a href="{r}{k}.html"{" aria-current=page" if k == cur else ""}>{v}</a></li>' for k, v in NAV)
    return (f'<a class="skip" href="#main">Skip to content</a><header class="nav"><a class="logo" href="{r}index.html">✻ <span data-site="name">{N}</span></a><button class="menu-btn" aria-expanded="false" aria-controls="menu">Menu</button>'
      f'<a class="btn btn-p" href="{r}quote.html">Request a Quote</a><ul id="menu">{li}<li><a data-call href="{r}contact.html">Call <span data-site="phone">(212) 555-0100</span></a></li></ul></header>')
def foot(r):
    return (f'<footer><div class="wrap g"><div><a class="logo" href="{r}index.html">✻ {N}</a><p>HVAC and climate engineering for homes and businesses.</p><p>Instagram · LinkedIn · Facebook</p></div>'
      f'<div><h3>Navigation</h3><ul><li><a href="{r}about.html">About</a></li><li><a href="{r}projects.html">Projects</a></li><li><a href="{r}insights.html">Insights</a></li><li><a href="{r}contact.html">Contact</a></li></ul></div>'
      f'<div><h3>Services</h3><ul><li><a href="{r}services/ac-repair.html">AC repair</a></li><li><a href="{r}services/ac-installation.html">Installation</a></li><li><a href="{r}services/hvac-maintenance.html">Maintenance</a></li><li><a href="{r}services/ventilation.html">Ventilation</a></li></ul></div>'
      f'<div><h3>Legal</h3><ul><li><a href="{r}privacy.html">Privacy</a></li><li><a href="{r}terms.html">Terms</a></li><li><a href="{r}faq.html">FAQ</a></li><li>© <span data-year></span> {N}</li></ul></div></div><div class="wrap wm" aria-hidden="true">✻ {N}</div></footer>'
      f'<div class="demo" role="note">Demo site · sample content</div><div class="bar"><a class="btn btn-p" data-call href="{r}contact.html">Call</a><a class="btn btn-g" data-text href="{r}contact.html">Text</a></div>')
def page(path, title, desc, h1, lead, body, cur="", img=None, noindex=False):
    r = "../" * path.count("/")
    side = f'<div class="pgi">{IMG(img, "Illustration for " + title, r)}</div>' if img else ""
    crumb = f'<p class="crumb"><a href="{r}index.html">Home</a> / {title}</p>' if path not in ("404.html", "thank-you.html") else ""
    html = (head(title, desc, r, noindex) + f'<body>{nav(r, cur)}<main id="main"><section class="pgh"><div class="wrap{" two" if img else ""}"><div>{crumb}<h1>{h1}</h1><p class="lead">{lead}</p></div>{side}</div></section>{body}</main>{foot(r)}<script src="{r}js/main.js"></script></body></html>')
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True); open(path, "w", encoding="utf-8").write(html)
sec = lambda inner, h="", alt=False, c=False: f'<section{" class=\"alt2\"" if alt else ""}><div class="wrap{" c" if c else ""}">{f"<h2>{h}</h2>" if h else ""}{inner}</div></section>'
card = lambda t, p, img=None, r="", extra="": f'<div class="cd">{IMG(img, t, r) if img else ""}<h3>{t}</h3><p>{p}</p>{extra}</div>'
grid = lambda xs: '<div class="g3">' + "".join(xs) + "</div>"
ul = lambda xs: '<ul class="lst">' + "".join(f"<li>{x}</li>" for x in xs) + "</ul>"
faq = lambda qs: '<div class="faq">' + "".join(f"<details><summary>{q}</summary><p>{a}</p></details>" for q, a in qs) + "</div>"
cta = lambda r="": sec(f'<div class="ctaband"><h2>Let’s engineer a better environment.</h2><p>Tell us what you need and we’ll get back to you.</p><a class="btn btn-p" href="{r}quote.html">Request a Quote</a> <a class="btn btn-g" data-call href="{r}contact.html">Call us</a></div>')
