PR = [("proj-store", "commercial", "Minimized downtime across a busy store", "Cooling upgraded after hours so trading was never interrupted."), ("proj-house", "residential", "Two-storey home returned to stable cooling", "Upstairs and downstairs balanced with a corrected duct layout."), ("proj-office", "commercial", "Office comfort restored before the deadline", "Ceiling cassette units replaced over a single weekend."), ("proj-server", "industrial", "Server room temperature stabilized overnight", "Airflow and cooling capacity corrected with no outage."), ("proj-heat", "maintenance", "Cooling restored before a summer heatwave", "Failed system diagnosed and repaired the same week."), ("blog-ducts", "ventilation", "Fresh-air upgrade for a clinic waiting room", "Ventilation rebalanced for comfort and air quality."), ("svc-refrigerant", "refrigeration", "Cold-room cooling restored for a café", "Refrigerant circuit repaired and tested, stock saved."), ("svc-commercial", "installation", "Rooftop units replaced on a three-storey office", "New units installed in phases to keep tenants comfortable.")]
